from decimal import Decimal

from django.db import models
from django.conf import settings

# Generated by Claude from a skectch of the schema on 10/20/2026 

class Profile(models.Model):
    # userId is both pk and fk -> OneToOne with primary_key=True
    user = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        primary_key=True,
        related_name="profile",
    )
    photo = models.ImageField(upload_to="profile_photos/", blank=True, null=True)

    def __str__(self):
        return f"Profile of {self.user}"


class Tag(models.Model):
    name = models.CharField(max_length=50, unique=True)

    def __str__(self):
        return self.name


class Unit(models.Model):
    name = models.CharField(max_length=20, unique=True)
    abbr = models.CharField(max_length=8, unique=True)

    def __str__(self):
        return self.abbr


class Ingredient(models.Model):
    name = models.CharField(max_length=50, unique=True)
    vegan = models.BooleanField(default=False)
    gluten_free = models.BooleanField(default=False)
    users = models.ManyToManyField(settings.AUTH_USER_MODEL, related_name="pantry", through="UserIngredient")

    def __str__(self):
        return self.name


class Recipe(models.Model):
    name = models.CharField(max_length=50)
    instructions = models.TextField()
    calories_per_serving = models.IntegerField()
    num_servings = models.IntegerField()
    prep_time = models.IntegerField(help_text="Preparation time (e.g. in minutes)")
    tags = models.ManyToManyField(Tag, related_name="tag_recipes", through="RecipeTag")
    ingredients = models.ManyToManyField(Ingredient, related_name="ingredient_recipes", through="RecipeIngredient")
    recipe_reviews = models.ManyToManyField(settings.AUTH_USER_MODEL, related_name="reviewed_recipes", through="Review")
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="recipes",
    )
    photo = models.ImageField(upload_to="recipe_photos/", blank=True, null=True)

    def __str__(self):
        return self.name

    # ------------------------------------------------------------ pantry use cases
    # Methods only (no new fields), so no migration is needed.

    def scale_batch(self, multiplier):
        """
        UC 51 Adjust Batch Size (class diagram: Recipe.scaleBatch).
        Returns [(ingredient, unit, scaled quantity)] for multiplier x the recipe.
        Nothing is saved; the stored recipe stays the same.
        """
        multiplier = Decimal(str(multiplier))
        if multiplier <= 0:
            raise ValueError("The batch size must be more than 0.")
        return [
            (ri.ingredient, ri.unit, (Decimal(ri.quantity) * multiplier).quantize(Decimal("0.01")))
            for ri in self.recipe_ingredients.select_related("ingredient", "unit")
        ]

    def multiplier_for(self, servings):
        """How much to scale the recipe to make `servings` servings."""
        return Decimal(servings) / Decimal(self.num_servings)

    def get_missing_ingredients(self, pantry, multiplier=1):
        """
        UC 53 Determine Missing Ingredients (class diagram: Recipe.getMissingIngredients).
        Returns [(ingredient, unit, needed, have)] for everything the pantry lacks.
        """
        have = {item.ingredient_id: item for item in pantry.items()}
        missing = []
        for ingredient, unit, needed in self.scale_batch(multiplier):
            item = have.get(ingredient.id)
            if item is None or item.unit_id != (unit.id if unit else None):
                missing.append((ingredient, unit, needed, 0))   # not there, or a different unit
            elif item.quantity < needed:
                missing.append((ingredient, unit, needed, item.quantity))
        return missing


class RecipeTag(models.Model):
    recipe = models.ForeignKey(Recipe, on_delete=models.CASCADE, related_name="recipe_tags")
    tag = models.ForeignKey(Tag, on_delete=models.CASCADE, related_name="recipe_tags")

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["recipe", "tag"], name="unique_recipe_tag"),
        ]


class RecipeIngredient(models.Model):
    recipe = models.ForeignKey(Recipe, on_delete=models.CASCADE, related_name="recipe_ingredients")
    ingredient = models.ForeignKey(Ingredient, on_delete=models.CASCADE, related_name="recipe_ingredients")
    unit = models.ForeignKey(
        Unit,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="recipe_ingredients",
    )
    quantity = models.IntegerField()

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["recipe", "ingredient"], name="unique_ingredient_per_recipe"
            ),
        ]


class UserIngredient(models.Model):
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="user_ingredients",
    )
    ingredient = models.ForeignKey(Ingredient, on_delete=models.CASCADE, related_name="user_ingredients")
    unit = models.ForeignKey(
        Unit,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="user_ingredients",
    )
    quantity = models.IntegerField()

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["user", "ingredient"], name="unique_ingredient_per_user_pantry"
            ),
        ]


class Favorite(models.Model):
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="favorites",
    )
    recipe = models.ForeignKey(Recipe, on_delete=models.CASCADE, related_name="favorites")

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["user", "recipe"], name="unique_favorite"),
        ]


class Review(models.Model):
    # Deleting the user keeps the review but orphans it
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="reviews",
    )
    recipe = models.ForeignKey(Recipe, on_delete=models.CASCADE, related_name="reviews")
    date = models.DateTimeField(auto_now_add=True)
    rating = models.IntegerField()
    comment = models.TextField(blank=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["user", "recipe"], name="one_review_per_user_per_recipe"),
        ]
